import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
import { t, label, collectionUrl, CONDITIONS } from '../util';
export function typeBadge(type, extra = '') {
  if (!type) return null;
  return m("span", {
    className: 'CurioTypeBadge ' + extra,
    style: {
      '--curio-accent': type.color()
    }
  }, m(Icon, {
    name: type.icon()
  }), " ", label(type.names()));
}
export function statusPill(status) {
  if (!status || status === 'owned') return null;
  return m("span", {
    className: 'CurioStatus CurioStatus--' + status
  }, m(Icon, {
    name: status === 'wishlist' ? 'far fa-heart' : 'fas fa-right-left'
  }), " ", t('status.' + status));
}
const PROGRESS_ICONS = {
  pending: 'far fa-circle',
  in_progress: 'fas fa-circle-half-stroke',
  completed: 'fas fa-circle-check',
  abandoned: 'fas fa-circle-xmark'
};

/** Not started, in progress, completed or abandoned, where the item's type tracks it. */
export function progressPill(item, type) {
  const progress = type?.progress() && item.status() !== 'wishlist' ? item.progress() : null;
  if (!progress) return null;
  return m("span", {
    className: 'CurioProgress CurioProgress--' + progress
  }, m(Icon, {
    name: PROGRESS_ICONS[progress]
  }), " ", t('progress.' + progress));
}

/** "Graded": a professionally graded copy, where the item's type offers it. Its photos show by whom and the score. */
export function gradedBadge(item, type) {
  if (!type?.grading() || !item.graded()) return null;
  return m("span", {
    className: "CurioGraded"
  }, m(Icon, {
    name: "fas fa-certificate"
  }), " ", t('item.graded'));
}

/** The image itself, blurred, fills whatever the whole picture leaves of its frame. */
export const backdrop = url => url ? {
  '--curio-cover': `url("${url.replace(/["\\\n]/g, encodeURIComponent)}")`
} : undefined;
export function cover(url, shape, wanted, alt = '') {
  return m("div", {
    className: 'CurioCover CurioCover--' + (shape || 'portrait') + (wanted ? ' CurioCover--wanted' : ''),
    style: backdrop(url)
  }, url ? m("img", {
    src: url,
    alt: alt,
    loading: "lazy"
  }) : m(Icon, {
    name: "fas fa-image",
    className: "CurioCover-empty"
  }));
}
export function owner(user, small) {
  if (!user) return null;
  return m(Link, {
    className: 'CurioOwner' + (small ? ' CurioOwner--small' : ''),
    href: app.route('user.curio', {
      username: user.slug()
    })
  }, m(Avatar, {
    user: user
  }), " ", m("strong", null, username(user)));
}

/** A collection as a card: its covers fanned out over a blur of the first. */
export function collectionCard(collection, attrs = {}) {
  const type = collection.type();
  const preview = collection.preview() || [];
  const shape = type ? type.shape() : 'portrait';
  return m(Link, Object.assign({
    className: 'CurioCard CurioCard--' + shape,
    href: collectionUrl(collection),
    style: {
      '--curio-accent': type?.color()
    }
  }, attrs), m("div", {
    className: "CurioCard-art"
  }, preview[0] ? m("div", {
    className: "CurioCard-blur",
    style: {
      backgroundImage: `url(${preview[0]})`
    }
  }) : null, m("div", {
    className: 'CurioCard-fan CurioCard-fan--' + preview.length
  }, preview.length ? preview.map(url => m("img", {
    src: url,
    alt: "",
    loading: "lazy"
  })) : m(Icon, {
    name: type?.icon() || 'fas fa-box-open',
    className: "CurioCard-empty"
  })), collection.featured() ? m("span", {
    className: "CurioCard-featured"
  }, m(Icon, {
    name: "fas fa-award"
  })) : null), m("div", {
    className: "CurioCard-body"
  }, typeBadge(type), m("h3", {
    className: "CurioCard-name"
  }, collection.name()), m("div", {
    className: "CurioCard-stats"
  }, m("span", null, t('count.items', {
    count: collection.ownedCount()
  })), collection.wishCount() ? m("span", null, t('count.wanted', {
    count: collection.wishCount()
  })) : null, collection.tradeCount() ? m("span", {
    className: "CurioCard-trade"
  }, t('count.trade', {
    count: collection.tradeCount()
  })) : null, collection.visibility() !== 'public' ? m("span", {
    className: "CurioCard-private",
    title: t('visibility.' + collection.visibility())
  }, m(Icon, {
    name: collection.visibility() === 'private' ? 'fas fa-lock' : 'fas fa-user-group'
  })) : null)));
}

/** Trading cards' own scale (TCGplayer's), each shown with its short code: "Near Mint (NM)". */
export const CARD_CONDITIONS = ['mint', 'near_mint', 'light_played', 'moderately_played', 'heavily_played', 'damaged'];

/** The conditions an item of this type can be in. */
export const conditionsFor = type => type?.conditionScale() === 'cards' ? CARD_CONDITIONS : CONDITIONS;

/** A condition's name on its type's scale (one kept from another scale still reads right). */
export const conditionText = (type, value) => {
  const cards = type?.conditionScale() === 'cards' ? CARD_CONDITIONS.includes(value) : !CONDITIONS.includes(value);
  return t((cards ? 'card_condition.' : 'condition.') + value);
};

/** The condition as a small coloured word, or null. */
export const conditionPill = (type, value) => value ? m("span", {
  className: 'CurioCond CurioCond--' + value
}, conditionText(type, value)) : null;
flarum.reg.add('ernestdefoe-curio', 'forum/components/bits', { typeBadge: typeBadge,statusPill: statusPill,progressPill: progressPill,gradedBadge: gradedBadge,backdrop: backdrop,cover: cover,owner: owner,collectionCard: collectionCard,CARD_CONDITIONS: CARD_CONDITIONS,conditionsFor: conditionsFor,conditionText: conditionText,conditionPill: conditionPill, });